// ─── PASTE YOUR VERIFY TOKEN HERE ────────────────────────────────────
//     The same string you type into Meta's "Verify token" box.
const META_VERIFY_TOKEN = '';
// ─────────────────────────────────────────────────────────────────────
//
// Meta calls every callback URL once with GET to verify ownership.

const q = $json.query || {};
const token = String(q['hub.verify_token'] || '');

let diff = token.length ^ META_VERIFY_TOKEN.length;
for (let i = 0; i < token.length && i < META_VERIFY_TOKEN.length; i++) {
  diff |= token.charCodeAt(i) ^ META_VERIFY_TOKEN.charCodeAt(i);
}
const ok = Boolean(META_VERIFY_TOKEN) && q['hub.mode'] === 'subscribe' && diff === 0;

return [{ json: { verified: ok, challenge: ok ? String(q['hub.challenge'] || '') : '' } }];

// ─── PASTE YOUR **INSTAGRAM** APP SECRET HERE ────────────────────────
//     Instagram → API setup with Instagram login → "Instagram app secret"
//
//     NOT the App Secret under App settings → Basic. That one belongs to
//     the Facebook app; this route signs webhooks with the Instagram app
//     secret. Both are 32 hex characters, so the wrong one fails only at
//     signature-check time, with no clue that it is the wrong value.
const META_APP_SECRET = '';
// ─────────────────────────────────────────────────────────────────────
//
// Meta signs every webhook POST with HMAC-SHA256 over the RAW body.
// n8n's Code sandbox exposes neither require() nor a crypto global, so
// SHA-256 and HMAC are implemented here in plain JavaScript. Verified
// byte-identical to Node's createHmac across block-boundary lengths and
// key sizes. Buffer is available in the sandbox and is used for I/O only.

if (!META_APP_SECRET) throw new Error('META_APP_SECRET is empty - refusing to process an unverified Meta webhook');

const K = new Uint32Array([
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2]);
const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

function sha256(bytes) {
  const H = new Uint32Array([0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                             0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]);
  const l = bytes.length;
  const padded = new Uint8Array(((l + 9) + 63) & ~63);
  padded.set(bytes); padded[l] = 0x80;
  const dv = new DataView(padded.buffer);
  const bits = l * 8;
  dv.setUint32(padded.length - 8, Math.floor(bits / 4294967296));
  dv.setUint32(padded.length - 4, bits >>> 0);
  const w = new Uint32Array(64);
  for (let off = 0; off < padded.length; off += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(off + t * 4);
    for (let t = 16; t < 64; t++) {
      const x = w[t-15], y = w[t-2];
      const s0 = (rotr(x,7) ^ rotr(x,18) ^ (x >>> 3)) >>> 0;
      const s1 = (rotr(y,17) ^ rotr(y,19) ^ (y >>> 10)) >>> 0;
      w[t] = (w[t-16] + s0 + w[t-7] + s1) >>> 0;
    }
    let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e,6) ^ rotr(e,11) ^ rotr(e,25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = (rotr(a,2) ^ rotr(a,13) ^ rotr(a,22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  const out = new Uint8Array(32), odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}

function hmacHex(keyBytes, msgBytes) {
  let k = keyBytes;
  if (k.length > 64) k = sha256(k);
  const key = new Uint8Array(64); key.set(k);
  const ipad = new Uint8Array(64 + msgBytes.length);
  const opad = new Uint8Array(64 + 32);
  for (let i = 0; i < 64; i++) { ipad[i] = key[i] ^ 0x36; opad[i] = key[i] ^ 0x5c; }
  ipad.set(msgBytes, 64);
  opad.set(sha256(ipad), 64);
  let s = '';
  for (const b of sha256(opad)) s += b.toString(16).padStart(2, '0');
  return s;
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = String(headers['x-hub-signature-256'] || '');

const b64 = item.binary && item.binary.data && item.binary.data.data;
if (!b64) throw new Error('Raw body missing - enable the "Raw Body" option on the webhook node');
const raw = Buffer.from(b64, 'base64');

const expected = 'sha256=' + hmacHex(
  new Uint8Array(Buffer.from(META_APP_SECRET, 'utf8')),
  new Uint8Array(raw));

// constant-time compare
let diff = signature.length ^ expected.length;
for (let i = 0; i < signature.length && i < expected.length; i++) {
  diff |= signature.charCodeAt(i) ^ expected.charCodeAt(i);
}
if (diff !== 0) throw new Error('Invalid X-Hub-Signature-256 - rejecting webhook');

return [{ json: { headers, body: JSON.parse(raw.toString('utf8')) } }];

// Turns one Instagram webhook into zero or more guest messages.
//
// Returning [] ends the branch cleanly - that is how non-conversational
// events are dropped. The filtering here is not cosmetic:
//
//   is_echo  - Meta fires a webhook for every message WE send. Without this
//              the agent reads its own reply and answers it, forever.
//   read /
//   delivery - receipts, not messages.
//   deleted  - retraction, nothing to answer.
//   no text  - a like, sticker or bare attachment. The agent has nothing to
//              work with and would invent a reply to nothing.

// ─── THE VILLA'S INSTAGRAM ACCOUNT ID ────────────────────────────────
//     Instagram → API setup → the account whose DMs this agent answers.
//     Not a secret; it is a public account identifier.
const VILLA_IG_ID = '17841475648867726';
// ─────────────────────────────────────────────────────────────────────

const b = $json.body || $json;
const entries = Array.isArray(b.entry) ? b.entry : [];
const out = [];

for (const entry of entries) {
  // `messaging` is the DM shape; `changes` appears on other subscriptions.
  const events = Array.isArray(entry.messaging) ? entry.messaging
               : Array.isArray(entry.changes)   ? entry.changes.map(c => c?.value).filter(Boolean)
               : Array.isArray(b.messaging)     ? b.messaging
               : [];

  for (const m of events) {
    if (!m || m.read || m.delivery || m.reaction) continue;

    // Other accounts can share this webhook — a tester's personal account
    // subscribed to the same app fires here too. Replying to those with the
    // villa's token fails at Meta ("Object with ID ... does not exist"), and
    // answering someone else's DMs would be wrong even if it worked.
    const addressedTo = m.recipient?.id;
    if (addressedTo && addressedTo !== VILLA_IG_ID) continue;

    const msg = m.message || {};
    if (msg.is_echo || msg.is_deleted) continue;

    const text = String(
      msg.text ||
      m.postback?.title ||
      msg.quick_reply?.payload ||
      ''
    ).trim();
    if (!text) continue;

    const senderId = m.sender?.id || '';
    if (!senderId) continue;

    out.push({ json: {
      channel: 'instagram',
      senderId,
      recipientId: m.recipient?.id || '',
      messageId: msg.mid || m.postback?.mid || '',
      text,
      sessionId: `instagram:${senderId}`,
      raw: b,
    }});
  }
}

return out;

const x=$input.first().json.body ?? $input.first().json;
return [{json:{
 event:"booking_lead",
 lead_id:x.lead_id||x.id||`lead_${Date.now()}`,
 guest_name:x.guest_name||x.name||"Guest",
 phone:x.phone||null,email:x.email||null,
 check_in:x.check_in||null,check_out:x.check_out||null,
 guests:Number(x.guests||1),budget:x.budget??null,
 message:x.message||"",
 property_id:x.property_id||null,
 source:x.source||"unknown",
 raw:x
}}];

const input=$input.first().json; const p=input.body ?? input;
const lead=$('Normalize Booking Lead').first().json;
return [{json:{lead,pms:p, prompt:`You are a Bougainvilla vacation-rental sales agent. Return STRICT JSON with keys decision,reply,alternative_request. Guest: ${lead.guest_name}. Dates: ${lead.check_in} to ${lead.check_out}. Guests: ${lead.guests}. Budget: ${lead.budget}. Message: ${lead.message}. Availability data: ${JSON.stringify(p)}. If available, be concise and move toward booking. Never invent price or availability. If unavailable, ask for alternative dates or property.`}}];

const r=$input.first().json; let c=r.choices?.[0]?.message?.content||"{}"; let a; try{a=JSON.parse(c)}catch(e){a={decision:"human_review",reply:c,alternative_request:null}};
const lead=$('Normalize Booking Lead').first().json;
return [{json:{ok:true,event:"booking_lead_processed",lead_id:lead.lead_id,guest_phone:lead.phone,decision:a.decision,reply:a.reply,alternative_request:a.alternative_request,requires_human:a.decision==="human_review"}}];

let c=$input.first().json.choices?.[0]?.message?.content||"{}";let a;try{a=JSON.parse(c)}catch(e){a={intent:"unknown",priority:"high",reply:c,needs_human:true}};
const x=$('Normalize Voice Event').first().json;
return [{json:{...x,ai:a,escalate:Boolean(a.needs_human)||a.priority==="urgent"}}];

// Runs per item: each lead keeps its own AI copy.
const src = $('Build Follow-up Messages').item.json;
const text = $json.choices?.[0]?.message?.content;
return { json: { lead_id: src.lead_id, phone: src.phone, message: text || 'Hi! Just checking if you still need help with your stay at Bougainvilla.' } };

// Runs per item: each property keeps its own recommendation.
const src = $('Build Pricing Prompt').item.json;
let a;
try { a = JSON.parse($json.choices?.[0]?.message?.content || '{}'); }
catch (e) { a = { recommended_price: null, reason: 'AI parse failure', confidence: 0, action: 'human_review' }; }
return { json: { property_id: src.property_id, current_price: src.current_price, recommendation: a, requires_approval: true } };

// ─── PASTE YOUR DASHBOARD KEY HERE ───────────────────────────────────
//     Same value as DASHBOARD_API_KEY in the Vercel project.
//     Generate with: openssl rand -hex 32
const DASHBOARD_API_KEY = '';
// ─────────────────────────────────────────────────────────────────────

if (!DASHBOARD_API_KEY) throw new Error('DASHBOARD_API_KEY is empty - refusing to serve metrics');

const got = String(($json.headers || {})['x-api-key'] || '');
let diff = got.length ^ DASHBOARD_API_KEY.length;
for (let i = 0; i < got.length && i < DASHBOARD_API_KEY.length; i++) {
  diff |= got.charCodeAt(i) ^ DASHBOARD_API_KEY.charCodeAt(i);
}
if (diff !== 0) throw new Error('Unauthorized dashboard request');

return [{ json: { authorized: true } }];

// dashboard_metrics() already returns the exact shape the page wants, so
// this only labels the source and guards the failure case.
//
// Pass every section through. An earlier version listed only stats and
// dropped bookings, which is why the booking tiles never appeared.
const r = $json || {};
const failed = !!r.error || !r.stats;

if (failed) {
  return [{ json: { source: 'no_db', generated_at: new Date().toISOString(),
                    detail: 'Supabase unreachable or schema not installed' } }];
}

return [{ json: {
  source: 'supabase',
  generated_at: new Date().toISOString(),
  stats: r.stats,
  channels: r.channels || {},
  message_series: r.message_series || { labels: [], values: [] },
  recent_leads: Array.isArray(r.recent_leads) ? r.recent_leads : [],
  bookings:  r.bookings  || null,
  occupancy: r.occupancy || null,
  economics: r.economics || null,
  tariff:    r.tariff    || null,
} }];

// Merge what the model read into what we already knew, and validate.
// Nothing here trusts the model further than a regex will carry it.
const ev = $('Normalize Instagram Event').item.json;
const st = $('Load Guest State').item.json || {};
const prev = st.slots || {};

let ex = {};
try {
  const raw = String(($json.choices && $json.choices[0] && $json.choices[0].message
    && $json.choices[0].message.content) || '').trim();
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) ex = JSON.parse(m[0]);
} catch (e) { ex = {}; }
// If Sarvam is down we land here with ex = {}. That is survivable: the guest
// still gets asked for the first empty slot. A dead model must not mean silence.

const clean = (v) => {
  const s = String(v == null ? '' : v).trim();
  return (!s || s === 'null' || s === 'undefined' || s === 'none' || s === 'N/A') ? '' : s;
};
const num = (v) => { const n = parseInt(clean(v), 10); return Number.isFinite(n) && n > 0 ? n : null; };

const today = st.today || new Date().toISOString().slice(0, 10);
const okDate = (s) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = Date.parse(s + 'T00:00:00Z');
  if (!Number.isFinite(d)) return false;
  const t = Date.parse(today + 'T00:00:00Z');
  return d >= t - 86400000 && d <= t + 550 * 86400000;   // not the past, not 2030
};
const okPhone = (s) => { const d = s.replace(/\D/g, ''); return d.length >= 10 && d.length <= 13 ? d : ''; };
const okName = (s) => (s.length >= 2 && s.length <= 60 && !/\d/.test(s)) ? s : '';

const newIn = clean(ex.check_in);
// "Those are taken, 23 September is free" - "yes please". That yes has to
// mean the date we offered, or the conversation dead-ends here.
const offered = String(st.offered_check_in || '').slice(0, 10);
const adopting = !okDate(newIn) && ex.agrees === true
              && st.conv_state === 'UNAVAILABLE' && okDate(offered);

const slots = {
  check_in:   okDate(newIn) ? newIn : (adopting ? offered : (prev.check_in || '')),
  nights:     num(ex.nights) || prev.nights || null,
  pax:        num(ex.pax)    || prev.pax    || null,
  occasion:   clean(ex.occasion)          || prev.occasion   || '',
  guest_name: okName(clean(ex.guest_name)) || prev.guest_name || '',
  phone:      okPhone(clean(ex.phone))     || prev.phone      || '',
};

// A new date means the old quote and hold are stale.
const datesChanged = okDate(newIn) && prev.check_in && newIn !== String(prev.check_in).slice(0, 10);

return { json: {
  channel: ev.channel, senderId: ev.senderId, messageId: ev.messageId,
  text: ev.text, today,
  slots,
  prevState:  st.conv_state || 'NEW',
  askedSlot:  st.asked_slot || '',
  askedCount: Number(st.asked_count || 0),
  holdLive:   Boolean(st.hold_live) && !datesChanged,
  datesChanged, adopting,
  agrees:     ex.agrees === true,
  declines:   ex.declines === true,
  wantsHuman: ex.wants_human === true,
  language:   ['en','hi','hinglish','mr'].includes(clean(ex.language)) ? clean(ex.language)
              : (st.last_language || 'en'),
  // quote_stay wants text and tolerates blanks
  q_check_in: slots.check_in || '',
  q_nights:   String(slots.nights || 1),
  q_pax:      slots.pax ? String(slots.pax) : '',
} };

// The state table. This is the determinism: the next question is chosen
// here, from the slots, and the model is only ever told what to say.
const m = $('Merge Guest Slots').item.json;
const s = m.slots;
const q = ($json && typeof $json === 'object' && !$json.error) ? $json : {};
const quoteFailed = !q || q.available === undefined;

const inr = (n) => '\u20b9' + Number(n).toLocaleString('en-IN');
const nice = (d) => {
  if (!d) return '';
  const dt = new Date(String(d).slice(0, 10) + 'T00:00:00Z');
  return dt.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' });
};

const nights = s.nights || 1;

// Agreement is sticky. Once a guest has said yes, giving their name is not a
// reason to start quoting at them again - which is exactly the loop we are
// here to kill.
const offerStood = m.prevState === 'QUOTED';
const committed  = ['NEEDS_NAME', 'NEEDS_PHONE'].includes(m.prevState);
const accepted   = committed || (m.agrees && offerStood);

let state, ask = '', reply = '', offering = '';

if (m.wantsHuman) {
  state = 'HUMAN';
  reply = 'Let me get someone from our team onto this - they will message you here shortly.';
} else if (m.holdLive && !m.datesChanged) {
  state = 'HELD';
  reply = 'That one is already held under ' + (s.guest_name || 'your name')
        + ' - our team will call to confirm. Anything else I can help with?';
} else if (!s.check_in) {
  state = 'NEW'; ask = 'check_in';
  reply = 'Happy to help. Which dates were you looking at?';
} else if (!s.pax) {
  state = 'DATES'; ask = 'pax';
  reply = 'Lovely - ' + nice(s.check_in) + '. How many guests will you be?';
} else if (quoteFailed || q.error) {
  state = 'NEW'; ask = 'check_in';
  reply = 'Sorry, I could not read those dates. Could you send the arrival date as a day and month?';
} else if (q.over_capacity) {
  state = 'HUMAN';
  reply = 'That is a larger group than the villa normally takes - let me get our manager to work it out with you.';
} else if (q.available === false) {
  state = 'UNAVAILABLE'; ask = 'check_in';
  offering = q.next_available_from || '';
  reply = nice(s.check_in) + ' is already taken, I am afraid.'
        + (offering ? ' The next free date is ' + nice(offering) + ' - would that work?'
                    : ' Could you tell me another date that suits you?');
} else if (m.declines && !accepted) {
  state = 'NEW'; ask = 'check_in';
  reply = 'No problem at all. Which other dates would suit you?';
} else if (!accepted) {
  state = 'QUOTED'; ask = 'confirm';
  reply = nice(q.check_in) + ' is free for ' + s.pax + ' guests - ' + inr(q.total)
        + ' for ' + nights + ' night' + (nights === 1 ? '' : 's') + '. Shall I hold it for you?';
} else if (!s.guest_name) {
  state = 'NEEDS_NAME'; ask = 'guest_name';
  reply = 'Lovely. What name should I put it under?';
} else if (!s.phone) {
  state = 'NEEDS_PHONE'; ask = 'phone';
  reply = 'And a number our caretaker can reach you on?';
} else {
  state = 'HOLD_PLACED';
  reply = 'Done - held for ' + (q.hold_hours || 24) + ' hours under ' + s.guest_name
        + '. Our team will call you on ' + s.phone + ' to confirm and take payment.';
}

// Asking the same thing three times is a failure, not persistence.
const askedCount = (ask && ask === m.askedSlot) ? m.askedCount + 1 : (ask ? 1 : 0);
if (ask && askedCount >= 3) {
  state = 'HUMAN'; ask = '';
  reply = 'I am not following - let me get someone from our team to help you directly.';
}

const needsHuman = state === 'HUMAN';
const placeHold  = state === 'HOLD_PLACED' && !m.holdLive;

return { json: {
  ...m,
  state, ask, askedCount, needsHuman, placeHold, offering,
  reply,                                   // the deterministic message
  quoteTotal: (state === 'QUOTED' || state === 'HOLD_PLACED') && q.total != null ? String(q.total) : '',
  facts: {
    available: q.available, total: q.total, nights: q.nights,
    check_in: q.check_in, check_out: q.check_out,
    next_available_from: q.next_available_from || null,
  },
} };

// The model's second and last job: say the sentence we chose, warmly,
// in the guest's language. It is given no facts it could get wrong.
const d = $json;
const langName = { en: 'English', hi: 'Hindi', hinglish: 'Hinglish (Roman script)', mr: 'Marathi' }[d.language] || 'English';

const prompt = [
  'You are the Bougainvilla Resorts booking assistant on Instagram.',
  'Rewrite the message below so it sounds warm and human, and send it in ' + langName + '.',
  '',
  'MESSAGE TO SEND:',
  '"""' + d.reply + '"""',
  '',
  'Rules:',
  '- Keep every fact exactly as written: the same dates, the same price, the',
  '  same name and number. Change nothing factual.',
  '- Add no new facts. No other prices, no discounts, no amenities, no policies,',
  '  no promises about confirmation or payment.',
  '- Ask only the question that is already there. Never add a second question.',
  '- One or two short sentences. No emoji spam, at most one. No greeting if the',
  '  conversation is already under way.',
  '- Return the message text only, with no quotes and no explanation.',
].join('\n');

return { json: { ...d, prompt } };

// Take the model's phrasing only if it stayed honest. Otherwise send the
// deterministic sentence, which is always correct if a little plain.
const d = $('Decide Next Question').item.json;
const fallback = d.reply;

let out = '';
try {
  out = String(($json.choices && $json.choices[0] && $json.choices[0].message
    && $json.choices[0].message.content) || '').trim();
} catch (e) { out = ''; }

out = out.replace(/^["'\u201c\u201d]+|["'\u201c\u201d]+$/g, '').trim();

// Every number of 1000 or more in the reply must be one we gave it. This is
// what stops a friendly model inventing a rate or a discount.
const bigNums = (t) => (String(t).replace(/[,\u00a0]/g, '').match(/\d{4,}/g) || []);
const allowed = bigNums(fallback);
const got = bigNums(out);
const invented = got.some((n) => !allowed.includes(n));
const dropped = allowed.some((n) => !got.includes(n));

const bad = !out || out.length < 2 || out.length > 600 || invented || dropped;

return { json: { ...d, reply: bad ? fallback : out, replySource: bad ? 'template' : 'model',
                 composeRejected: bad && !!out } };
